def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The 9-cell pattern is the stamp; the 2s mark where its center goes.
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 9]
    if not cells:
        return out
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    pattern = [(r-r0, c-c0) for r, c in cells]
    ar = (max(r for r, c in pattern) + 1) // 2
    ac = (max(c for r, c in pattern) + 1) // 2

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                for dr, dc in pattern:
                    rr, cc = r + dr - ar, c + dc - ac
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 9
    return out
